	public static void verifyModel(SailRepository repository, Model expected, String phase) {
		Set<Statement> seen = new HashSet<>();
		try (RepositoryConnection connection = repository.getConnection();
				RepositoryResult<Statement> statements = connection.getStatements(null, null, null, false)) {
			while (statements.hasNext()) {
				Statement statement = statements.next();
				require(expected.contains(statement), "unexpected complete lexical statement: " + statement);
				require(seen.add(statement), "duplicate public statement: " + statement);
			}
		}
		require(seen.size() == expected.size(), "complete model cardinality " + seen.size() + "/" + expected.size());
		System.out.println("verified phase=" + phase + " allModelStatements=" + seen.size());
	}

	/** Inspect the actual native named databases only after all owning repository handles have closed. */
	public static void verifyClosedIndexes(Path store, long expectedRows) throws Exception {
		Properties properties = new Properties();
		try (InputStream stream = Files.newInputStream(store.resolve("store.properties"))) {
			properties.load(stream);
		}
		require(INDEXES.equals(properties.getProperty("triple-indexes")), "persisted ordered index specification");
		try (MemoryStack stack = stackPush()) {
			PointerBuffer pointer = stack.mallocPointer(1);
			check(mdb_env_create(pointer));
			long env = pointer.get(0);
			try {
				check(mdb_env_set_maxdbs(env, 256));
				check(mdb_env_open(env, store.resolve("triples").toString(), MDB_RDONLY | MDB_NOTLS, 0664));
				check(mdb_txn_begin(env, 0, MDB_RDONLY, pointer));
				long txn = pointer.get(0);
				try {
					IntBuffer database = stack.mallocInt(1);
					for (String index : INDEX_NAMES) {
						for (boolean explicit : new boolean[] { true, false }) {
							String name = index + index + (explicit ? "" : "-inf");
							check(mdb_dbi_open(txn, name, 0, database));
							MDBStat stat = MDBStat.malloc(stack);
							check(mdb_stat(txn, database.get(0), stat));
							require(stat.ms_entries() == (explicit ? expectedRows : 0),
									"actual native rows in " + name);
							System.out.println("created-index name=" + name + " entries=" + stat.ms_entries());
						}
					}
					check(mdb_dbi_open(txn, (CharSequence) null, 0, database));
					check(mdb_cursor_open(txn, database.get(0), pointer));
					long cursor = pointer.get(0);
					try {
						MDBVal key = MDBVal.malloc(stack);
						MDBVal value = MDBVal.malloc(stack);
						int operation = MDB_FIRST;
						while (true) {
							int result = mdb_cursor_get(cursor, key, value, operation);
							if (result == MDB_NOTFOUND) {
								break;
							}
							check(result);
							byte[] bytes = new byte[(int) key.mv_size()];
							key.mv_data().get(bytes);
							String name = new String(bytes, StandardCharsets.UTF_8);
							if (name.matches("[spoc]{8}(-inf)?")
									&& name.substring(0, 4).equals(name.substring(4, 8))) {
								require(Set.of(INDEX_NAMES).contains(name.substring(0, 4)),
										"unexpected actual triple index: " + name);
							}
							System.out.println("native-catalog-key=" + name);
							operation = MDB_NEXT;
						}
					} finally {
						mdb_cursor_close(cursor);
					}
				} finally {
					mdb_txn_abort(txn);
				}
			} finally {
				mdb_env_close(env);
			}
		}
	}

	public static void require(boolean condition, String message) {
		if (!condition) {
			throw new AssertionError(message);
		}
	}

	private static void check(int result) {
		require(result == 0, "native diagnostic error=" + result);
	}

	/** Calls only async-profiler's public API; no private RDF4J fields or handles are accessed. */
	public static final class Profile implements AutoCloseable {
		private final Object profiler;
		private final Method execute;
		private final Path file;

		public Profile(Path directory) throws Exception {
			file = directory.resolve("ingestion-wall.jfr").toAbsolutePath();
			String lib = System.getProperty("rdf4j.matrix.profilerLibrary");
			if (lib == null) {
				profiler = null;
				execute = null;
				return;
			}
			Class<?> api = Class.forName("one.profiler.AsyncProfiler");
			profiler = api.getMethod("getInstance", String.class).invoke(null, lib);
			execute = api.getMethod("execute", String.class);
			System.out.println("profiler-start=" + execute.invoke(profiler,
					"start,event=wall,interval=10ms,cstack=fp,jfr,file=" + file));
		}

		@Override
		public void close() throws Exception {
			if (profiler != null) {
				System.out.println("profiler-stop=" + execute.invoke(profiler, "stop,jfr,file=" + file));
				require(Files.size(file) > 0, "positive profiler output");
			}
		}
	}
